properties.query:
// Service Ticket #4231548 - Sentinel - Cover Windows Registry ControlSet00x in addition to CurrentControlSet
// Detects persistence via registry keys
// Attackers use legit binaries to set reg keys enabling persistence.
let ProcessNames = dynamic(["reg.exe"]);
let parent_processes = dynamic(["cmd.exe","powershell.exe"]);
let cmd_all = dynamic(["/v","/t"]); // removed "/d 0" as there might be multiple spaces
let cmd_any = dynamic([
    "\\SYSTEM\\ControlSet001\\Control\\Terminal Server\\Utilities\\query",
    "\\SYSTEM\\ControlSet002\\Control\\Terminal Server\\Utilities\\query",
    "\\SYSTEM\\CurrentControlSet\\Control\\Terminal Server\\Utilities\\query"
]);
_Im_ProcessCreate(targetprocess_has_any=ProcessNames,parentprocess_has_any=parent_processes,commandline_has_all=cmd_all,commandline_has_any=cmd_any)
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
